import * as React from "react";

export type RingIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function RingIcon({ size = 20, ...props }: RingIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx={12} cy={14.5} r={5.5} />
      <path d="M9 10 12 4.5 15 10" />
    </svg>
  );
}
